   "cpp": "#include <iostream>\nusing namespace std;\n\nlong long power(long long a, long long b, long long m) {\n    // TODO: write your solution here\n    return 0;\n}\n\nint main() {\n    long long a, b, m;\n    cin >> a >> b >> m;\n    cout << power(a, b, m) << \"\\n\";\n    return 0;\n}\n",
