   "c": "#include <stdio.h>\n\nlong long power(long long a, long long b, long long m) {\n    if (b == 0) return 1 % m;\n    long long half = power(a, b / 2, m);\n    long long result = half * half % m;\n    if (b % 2 == 1) result = result * (a % m) % m;\n    return result;\n}\n\nint main(void) {\n    long long a, b, m;\n    scanf(\"%lld %lld %lld\", &a, &b, &m);\n    printf(\"%lld\\n\", power(a, b, m));\n    return 0;\n}\n",
