   "cpp": "#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct Node { int val; Node *next = nullptr; };\n\nint main() {\n    int n, pos;\n    cin >> n;\n    vector<Node *> nodes(n);\n    for (int i = 0; i < n; i++) {\n        nodes[i] = new Node;\n        cin >> nodes[i]->val;\n        if (i) nodes[i - 1]->next = nodes[i];\n    }\n    cin >> pos;\n    if (pos >= 0) nodes[n - 1]->next = nodes[pos];\n    Node *head = nodes[0];\n    Node *slow = head, *fast = head;\n    while (fast && fast->next) {\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) { cout << \"true\\n\"; return 0; }\n    }\n    cout << \"false\\n\";\n    return 0;\n}\n",
