   "c": "#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    int q;\n    scanf(\"%d\", &q);\n    int stack[1000], mins[1000], top = -1;\n    for (int i = 0; i < q; i++) {\n        char op[16];\n        scanf(\"%15s\", op);\n        if (strcmp(op, \"push\") == 0) {\n            int x;\n            scanf(\"%d\", &x);\n            stack[++top] = x;\n            mins[top] = (top == 0 || x < mins[top - 1]) ? x : mins[top - 1];\n        } else if (strcmp(op, \"pop\") == 0) top--;\n        else if (strcmp(op, \"top\") == 0) printf(\"%d\\n\", stack[top]);\n        else printf(\"%d\\n\", mins[top]);\n    }\n    return 0;\n}\n",
   "cpp": "#include <algorithm>\n#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nint main() {\n    int q;\n    cin >> q;\n    stack<int> st, mins;\n    for (int i = 0; i < q; i++) {\n        string op;\n        cin >> op;\n        if (op == \"push\") {\n            int x;\n            cin >> x;\n            st.push(x);\n            mins.push(mins.empty() ? x : min(x, mins.top()));\n        } else if (op == \"pop\") { st.pop(); mins.pop(); }\n        else if (op == \"top\") cout << st.top() << \"\\n\";\n        else cout << mins.top() << \"\\n\";\n    }\n    return 0;\n}\n",
